    {
      // ---- LOAD: stage column k of A into local buffer ----
    load_acol:
      for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=60 max=60
        a_col[i] = A[i][k];
      }

      // ---- COMPUTE: norm of column k from local buffer ----
      nrm = 0.0;
    nrm_loop:
      for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=60 max=60
        nrm += a_col[i] * a_col[i];
      }

      double r_kk = sqrt(nrm);
      R[k][k] = r_kk;

